//! Integrated inference coordinator: deterministic fast path, operator aliases, model fallback, reviewed skills and evidence.
use crate::{indexed::{Indexed,Result,Retrieved},router::{self,Route,Answer,SemanticRouter},policy::{Policy,Verdict},cognition::{Memory,Working},language::{Language,render}};
#[derive(Debug)]pub struct Response{pub text:String,pub path:&'static str,pub model_called:bool,pub complete:bool}
pub struct Engine<'a>{pub knowledge:&'a Indexed,pub memory:&'a Memory,pub policy:&'a Policy,pub model:Option<&'a dyn SemanticRouter>,pub language:Language}
impl Engine<'_>{
 fn canonical(&self,r:Route)->Result<Route>{Ok(match r{Route::Lookup{subject,relation}=>Route::Lookup{subject:self.policy.canonical("subject",&subject)?,relation:self.policy.canonical("relation",&relation)?},Route::Category{category}=>Route::Category{category:self.policy.canonical("category",&category)?},Route::Chain{subject,first,second}=>Route::Chain{subject:self.policy.canonical("subject",&subject)?,first:self.policy.canonical("relation",&first)?,second:self.policy.canonical("relation",&second)?},x=>x})}
 fn render_claims(&self,r:Retrieved)->Result<String>{let mut text=render(&r,self.language);for f in &r.facts{if let Some(review)=self.policy.assessment(f)?{text.push_str(&format!("\nOperator review of {:?}: {:?} by {:?}; {:?}",(&f.subject,&f.relation,&f.object),review.verdict,review.reviewer,review.rationale));}}Ok(text)}
 pub fn ask(&self,q:&str)->Result<Response>{
 let mut work=Working::new(512*1024);if q.len()>4096{return Err("question limit".into())}work.push(q.into())?;
 if let Some(x)=q.strip_prefix("recall "){let hits=self.memory.recall(x,128,4)?;let mut t=String::from("Historical cases, not verified current answers:");for(e,score)in hits{t.push_str(&format!("\n{} {:.3} {:?} -> {:?}",e.id,score,e.cue,e.outcome));}return Ok(Response{text:t,path:"episodic",model_called:false,complete:false});}
 if let Some(x)=q.strip_prefix("skill "){let mut words=x.split_whitespace();let name=words.next().ok_or("missing skill name")?;let args=words.map(str::parse::<i64>).collect::<std::result::Result<Vec<_>,_>>()?;if args.len()>8{return Err("argument limit".into())}let v=self.memory.latest_version(name)?.ok_or("unknown skill")?;if !self.policy.skill_approved(name,v)?{return Err("latest skill version not approved".into())}let n=self.memory.run_skill(name,Some(v),&args)?;return Ok(Response{text:n.to_string(),path:"approved_procedure",model_called:false,complete:true});}
 let mut route=self.canonical(router::choose(q,None)?)?;let mut answer=router::execute(self.knowledge,q,route.clone())?;
 let missing=matches!(&answer,Answer::Unknown{..})||matches!(&answer,Answer::Claims(r) if r.facts.is_empty()&&!r.truncated);
 let mut called=false;if missing{if let Some(m)=self.model{called=true;route=self.canonical(router::validate(m.route(q)?)?)?;answer=router::execute(self.knowledge,q,route)?;}}
 let (text,path,complete)=match answer{
 Answer::Claims(r)=>{let complete=!r.truncated&&!r.facts.is_empty()&&r.facts.iter().all(|f|self.policy.assessment(f).ok().flatten().map(|r|r.verdict)==Some(Verdict::Accepted));(self.render_claims(r)?,"knowledge",complete)},
 Answer::Number(n)=>(n.to_string(),"arithmetic",true),
 Answer::Paths(p)=>{let mut t=String::from("Unverified evidence paths:");for x in p.paths{t.push_str(&format!("\n{:?} -> {:?}",x.first,x.second));}(t,"relationship",false)},
 Answer::Unknown{suggested_categories}=>(format!("Unsupported question; suggested categories: {suggested_categories:?}"),"abstain",false)};
 work.push(text.clone())?;Ok(Response{text,path,model_called:called,complete})
 }
}
#[test]fn integrated_paths(){use crate::{indexed::Limits,store::parse_tsv,skills::{Skill,Expr},policy::Review};use std::path::Path;let mut d=Indexed::create(Path::new(":memory:"),Limits::default()).unwrap();d.insert(&parse_tsv("France\tcapital\tParis\tgeo\tsource").unwrap()).unwrap();let mut m=Memory::open(Path::new(":memory:")).unwrap();let p=Policy::open(Path::new(":memory:")).unwrap();p.alias("relation","capital city","capital").unwrap();let s=Skill{name:"five".into(),arity:0,body:Expr::Const{value:5}};let v=m.publish_skill(&s).unwrap();let e=Engine{knowledge:&d,memory:&m,policy:&p,model:None,language:Language::English};assert!(e.ask("What is the capital city of France?").unwrap().text.contains("Paris"));assert!(!e.ask("What is the capital city of France?").unwrap().complete);assert!(e.ask("skill five").is_err());p.approve_skill("five",v).unwrap();assert_eq!(e.ask("skill five").unwrap().text,"5");p.review("France","capital","Paris",&Review{verdict:Verdict::Accepted,reviewer:"test".into(),rationale:"fixture".into()}).unwrap();assert!(e.ask("What is the capital city of France?").unwrap().complete);assert_eq!(e.ask("calculate 3 * 9").unwrap().text,"27");}
